INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @post_id,'_rank_math_description','آموزش جامع انتخاب، نصب و نگهداری نوار تیپ با فاصله قطره‌چکان ۲۰ سانتی‌متر؛ بررسی ضخامت، فشار کاری، فیلتراسیون و نکات فنی برای بهینه‌سازی سیستم‌های آبیاری.' WHERE @created_post=1 AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@post_id AND meta_key='_rank_math_description');
